INSERT INTO roles(id,name) VALUES (1,'STUDENT'),(2,'INSTRUCTOR');
INSERT INTO topics(id,slug,title) VALUES (1,'arrays','Arrays');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (1,1,'arrays','Arrays','An array keeps values in indexed slots. Access reads a slot; update replaces it. Inserting opens a slot by shifting right, while deletion closes a gap by shifting left.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (1,1,'arrays','Arrays');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (1,1,'1.0.0','1.0.0','Index access/update O(1); insertion/deletion O(n); storage O(n).','Valid indices lie in [0,n); insert permits index n. Shifts preserve the order of other elements.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (1,1,'arrays.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (1,1,1,'What is the worst-case time to insert at the beginning of an array?','Every existing element may need to shift one slot.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (10,1,0,'O(1)',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (11,1,1,'O(n)',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (12,1,2,'O(log n)',0);
INSERT INTO topics(id,slug,title) VALUES (2,'linear-search','Linear search');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (2,2,'linear-search','Linear search','Linear search checks each element in order. It works on unsorted inputs and stops at the first equal value.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (2,2,'linear-search','Linear search');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (2,2,'1.0.0','1.0.0','O(n) time, O(1) extra space.','All indices before the cursor have been checked; the first match is returned.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (2,2,'linear-search.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (2,2,1,'Which duplicate does this linear search return?','The scan stops immediately at the first equal value.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (20,2,0,'The first match',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (21,2,1,'The last match',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (22,2,2,'All matches',0);
INSERT INTO topics(id,slug,title) VALUES (3,'binary-search','Binary search');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (3,3,'binary-search','Binary search','Binary search compares the midpoint of an ascending array, discarding the half that cannot contain the target. Any matching duplicate may be returned. Unsorted inputs are rejected.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (3,3,'binary-search','Binary search');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (3,3,'1.0.0','1.0.0','O(log n) time, O(1) extra space.','If a target is present, it remains in the inclusive [lo,hi] interval.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (3,3,'binary-search.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (3,3,1,'What prerequisite does binary search need?','Only ordering justifies discarding half of the remaining interval.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (30,3,0,'Distinct values',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (31,3,1,'Sorted ascending input',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (32,3,2,'Positive values',0);
INSERT INTO topics(id,slug,title) VALUES (4,'insertion-sort','Insertion sort');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (4,4,'insertion-sort','Insertion sort','Take a key from the unsorted suffix, shift larger prefix values right, then place the key. It is stable and adapts to nearly sorted inputs.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (4,4,'insertion-sort','Insertion sort');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (4,4,'1.0.0','1.0.0','O(n²) worst/average time, O(n) best time, O(1) extra space.','Before iteration i, the prefix [0,i) is sorted. Equal elements are not shifted past one another.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (4,4,'insertion-sort.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (4,4,1,'Why does this insertion sort preserve equal-value order?','The strict greater-than comparison leaves existing equal values before the key.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (40,4,0,'It shifts only strictly larger values',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (41,4,1,'It chooses random pivots',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (42,4,2,'It uses a queue',0);
INSERT INTO topics(id,slug,title) VALUES (5,'merge-sort','Merge sort');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (5,5,'merge-sort','Merge sort','Bottom-up merge sort merges runs of increasing width. Ties choose from the left run, preserving stability. Buffer reads and array writes are separate events.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (5,5,'merge-sort','Merge sort');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (5,5,'1.0.0','1.0.0','O(n log n) time, O(n) auxiliary space.','Each pass merges adjacent sorted runs of width w into sorted runs of width 2w.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (5,5,'merge-sort.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (5,5,1,'How much auxiliary space does this merge sort use?','A temporary buffer holds values from each merged run.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (50,5,0,'O(1)',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (51,5,1,'O(log n)',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (52,5,2,'O(n)',1);
INSERT INTO topics(id,slug,title) VALUES (6,'quick-sort','Quicksort');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (6,6,'quick-sort','Quicksort','An iterative Lomuto partition uses the final value as pivot and an explicit range stack. Equal values go left. This version is not stable; sorted or equal inputs can be quadratic.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (6,6,'quick-sort','Quicksort');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (6,6,'1.0.0','1.0.0','O(n log n) average, O(n²) worst time; O(n) bounded explicit range stack.','Within a partition, values before the boundary are ≤ pivot; later scanned values are > pivot.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (6,6,'quick-sort.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (6,6,1,'Which input can cause quadratic behavior with a final-element pivot?','A final-element pivot on ordered data can repeatedly produce a highly unbalanced partition.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (60,6,0,'Already sorted input',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (61,6,1,'Only empty input',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (62,6,2,'No input',0);
INSERT INTO topics(id,slug,title) VALUES (7,'linked-list','Singly linked list');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (7,7,'linked-list','Singly linked list','A singly linked list stores nodes joined by next links. Insert/delete use an index; search returns the first matching node ID. IDs represent conceptual identity, never browser addresses.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (7,7,'linked-list','Singly linked list');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (7,7,'1.0.0','1.0.0','O(n) indexed insert/delete/search/traverse; O(1) relinking after the predecessor is located. O(n) space.','The head reaches each active node once; the last next ID is 0 (null). Node IDs remain stable during an operation.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (7,7,'linked-list.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (7,7,1,'Which link changes when inserting after an existing node?','The new node points to the old successor and the predecessor points to the new node.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (70,7,0,'The predecessor’s next link',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (71,7,1,'Every node value',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (72,7,2,'No links',0);
INSERT INTO topics(id,slug,title) VALUES (8,'stack','Stack');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (8,8,'stack','Stack','A stack adds and removes values at one end. This release uses an array-backed stack, rejects underflow and caps capacity at 32.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (8,8,'stack','Stack');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (8,8,'1.0.0','1.0.0','Push/pop/peek O(1); O(n) storage.','The top is the last occupied element; only the top is removed.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (8,8,'stack.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (8,8,1,'Which value is popped first?','Stacks follow last-in-first-out order.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (80,8,0,'The oldest value',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (81,8,1,'The most recently pushed value',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (82,8,2,'The smallest value',0);
INSERT INTO topics(id,slug,title) VALUES (9,'queue','Queue');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (9,9,'queue','Queue','A queue appends at the back and removes from the front. This teaching implementation shifts on dequeue; a circular-buffer extension can make dequeue constant time.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (9,9,'queue','Queue');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (9,9,'1.0.0','1.0.0','Enqueue/inspect O(1); dequeue O(n) in this compact shifting implementation; O(n) storage.','The front is index 0; dequeue preserves the relative order of the remaining values.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (9,9,'queue.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (9,9,1,'Which value leaves a FIFO queue first?','First-in-first-out removes the earliest enqueued value.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (90,9,0,'The newest value',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (91,9,1,'The oldest value',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (92,9,2,'The largest value',0);
INSERT INTO topics(id,slug,title) VALUES (10,'bst','Binary search tree');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (10,10,'bst','Binary search tree','BSTs follow comparisons down the tree. Two-child deletion transplants the inorder successor, preserving node IDs. Traversals visit left/node/right (inorder), node/left/right (preorder), or left/right/node (postorder).');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (10,10,'bst','Binary search tree');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (10,10,'1.0.0','1.0.0','Search/insert/delete O(h); traversals O(n). h may be n in an unbalanced tree; O(n) storage.','All left descendants are strictly smaller and all right descendants strictly larger. Duplicate inserts are ignored.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (10,10,'bst.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (10,10,1,'Which traversal lists BST values in ascending order?','Inorder visits the smaller subtree, the node, then the larger subtree.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (100,10,0,'Preorder',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (101,10,1,'Inorder',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (102,10,2,'Postorder',0);
INSERT INTO topics(id,slug,title) VALUES (11,'graph','Graph editor');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (11,11,'graph','Graph editor','Build a graph with at most 16 vertices. Node IDs range from 1 to 31. Edges use integer weights, including zero; direction is explicit. Graph edits are executed by the C engine.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (11,11,'graph','Graph editor');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (11,11,'1.0.0','1.0.0','Adjacency-matrix edge lookup O(1); node removal O(V²); space O(V²).','Node IDs are unique; undirected edges are symmetric. Parallel edges replace their previous weight; self-loops are allowed.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (11,11,'graph.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (11,11,1,'What does an undirected edge mean?','The C adjacency matrix stores both directions.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (110,11,0,'Travel is possible in both directions',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (111,11,1,'Only the smaller ID can be the source',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (112,11,2,'Its weight must be zero',0);
INSERT INTO topics(id,slug,title) VALUES (12,'bfs','Breadth-first search');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (12,12,'bfs','Breadth-first search','BFS visits the source, then its neighbors, then the next layer. It follows outgoing edges in directed graphs and ignores weights. Unreachable vertices are not visited.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (12,12,'bfs','Breadth-first search');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (12,12,'1.0.0','1.0.0','O(V²) with this adjacency matrix; O(V) frontier/visited space.','Vertices are marked on enqueue, so each reachable vertex enters the queue once.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (12,12,'bfs.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (12,12,1,'Which structure manages the BFS frontier?','A FIFO queue visits earlier layers before later ones.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (120,12,0,'Stack',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (121,12,1,'Queue',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (122,12,2,'BST',0);
INSERT INTO topics(id,slug,title) VALUES (13,'dfs','Depth-first search');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (13,13,'dfs','Depth-first search','DFS uses an explicit stack and a per-vertex neighbor cursor. It descends to the first unvisited outgoing neighbor in input order, then backtracks. Weights are ignored.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (13,13,'dfs','Depth-first search');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (13,13,'1.0.0','1.0.0','O(V²) with this adjacency matrix; O(V) explicit stack space.','Each active stack path follows graph edges; marked vertices are never entered twice.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (13,13,'dfs.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (13,13,1,'When does DFS backtrack?','DFS returns to the parent after exhausting the current vertex’s unvisited neighbors.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (130,13,0,'When the current vertex has no unvisited outgoing neighbors',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (131,13,1,'After every edge regardless of state',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (132,13,2,'Only when every graph vertex is reachable',0);
INSERT INTO topics(id,slug,title) VALUES (14,'dijkstra','Dijkstra shortest paths');
INSERT INTO lessons(id,topic_id,slug,title,body) VALUES (14,14,'dijkstra','Dijkstra shortest paths','Dijkstra computes shortest distances from a source using nonnegative integer weights. Zero-weight edges are supported. Unreachable vertices retain infinity. All negative edges are rejected, including unreachable ones.');
INSERT INTO algorithms(id,lesson_id,slug,title) VALUES (14,14,'dijkstra','Dijkstra shortest paths');
INSERT INTO algorithm_versions(id,algorithm_id,version,engine_version,complexity,invariants) VALUES (14,14,'1.0.0','1.0.0','O(V²) time using linear minimum selection; O(V) distance/visited space.','The selected unsettled vertex has minimum tentative distance. With nonnegative edges its distance is final.');
INSERT INTO questions(id,lesson_id,stable_key) VALUES (14,14,'dijkstra.concept.1');
INSERT INTO question_revisions(id,question_id,revision,prompt,explanation) VALUES (14,14,1,'Why reject negative weights?','A later path through a negative edge could improve an already settled vertex.');
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (140,14,0,'They invalidate the settled-distance argument',1);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (141,14,1,'They cannot be stored as integers',0);
INSERT INTO answer_options(id,revision_id,ordinal,text,is_correct) VALUES (142,14,2,'They require an undirected graph',0);
